/* Built on `.btn`, so everything a button already decides (the brand fill and
 * its hover and pressed steps, the radius, the focus ring, the disabled state)
 * arrives from Button.css and is NOT repeated here. What is left is the one
 * behaviour that belongs to this component: a circle at rest that grows its
 * label when the pointer arrives, or while `data-expanded` holds it open.
 *
 * These rules override `.btn` at the same specificity and win on order:
 * Button.css is a dependency of this module, so the bundler emits it first.
 * That is the same bet `.nav-drawer-button` makes on `.icon-button`. */
.expand-button {
  gap: 0;
  min-width: var(--control-height);
  /* AS WIDE AS ITS CONTENT AND NEVER WIDER. `inline-flex` says that in a block
   * parent and stops saying it the moment the button is a flex or grid item:
   * a column Stack stretches its children by default, so the collapsed circle
   * was drawn as a 500px blue pill with a plus in the middle of it (owner, read
   * off the gallery, 2026-08-29). `min-width` is a floor and floors do not cap.
   * The hover state still grows, because max-content follows the label as it is
   * revealed. */
  inline-size: max-content;
  padding-inline: 0;
  /* Its own type, kept as it shipped: a label that is only there on hover reads
   * smaller and lighter than the one on a pill that always carries words. */
  font-size: var(--font-sm);
  font-weight: var(--font-weight-regular);
  transition: background var(--duration-fast), gap var(--duration-fast), padding var(--duration-fast), min-width var(--duration-fast);
  overflow: hidden;
}
/* THE GLYPH LEADS HERE, and this is the one place in the system where it does.
 * `.btn > .icon` carries `order: 1` so every mark in a button trails its label;
 * that rule is for a button whose label is the control. This one has no label
 * at rest, so the glyph IS the control and the words grow to the right of it.
 * Written with `.btn` in the selector to beat that rule on specificity rather
 * than on file order, because getting it wrong puts the plus after the words
 * and nothing else would say so. */
.btn.expand-button > .icon { order: 0; }

.expand-button:hover,
.expand-button[data-expanded] {
  padding: 0 var(--space-3);
  min-width: 0;
  gap: var(--space-1);
}
/* Held open answers like hovered, which is what `.btn[data-open]` already says
 * for every other trigger in the family. This component's open state has its own
 * attribute name (`expanded`, its public prop), so it asks for the same fill by
 * name rather than inheriting it. */
.expand-button[data-expanded] { background: var(--primary-hover); }

.expand-button-label,
.expand-button-chevron {
  max-width: 0;
  opacity: 0;
  transition: max-width var(--duration-fast), opacity var(--duration-fast);
  overflow: hidden;
  white-space: nowrap;
}
.expand-button:hover .expand-button-label,
.expand-button:hover .expand-button-chevron,
.expand-button[data-expanded] .expand-button-label,
.expand-button[data-expanded] .expand-button-chevron {
  max-width: 8rem;   /* label reveal cap */
  opacity: 1;
}

import './ExpandButton.css'
import { type ButtonHTMLAttributes, type Ref } from 'react'
import { cn } from '../lib/cn'
import { Button } from '../Button'
import { Icon, type IconName } from '../Icon'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Forwarded to the underlying <button>. */
  ref?: Ref<HTMLButtonElement>
  /** Icon shown always (collapsed and expanded state). */
  icon: IconName
  /** Label shown when expanded (hover or active). */
  label: string
  /** Show a chevron indicating dropdown / disclosure. */
  withChevron?: boolean
  /** Force expanded state (for use inside open dropdowns). */
  expanded?: boolean
}

/**
 * A BRAND-FILLED ICON THAT GROWS ITS LABEL WHEN THE POINTER ARRIVES. At rest it
 * is a circle carrying one glyph; on hover, on focus and while `expanded` is
 * set it widens into a pill and the words appear. That is the whole component,
 * and it is for the ONE action a screen offers everywhere — new, add, ask —
 * where a full pill would take room on every screen it appears on.
 *
 * It is NOT a disclosure caret, whatever the name suggests: it does not rotate,
 * and `withChevron` adds a mark that appears WITH the label rather than turning.
 * A row that opens a panel below it is <Accordion>, and a menu is
 * <ButtonGroup menu>.
 * This description used to say "the chevron that opens and closes a row", which
 * described a component that was never here (2026-08-29).
 *
 * The label is the accessible name at every size, so the collapsed circle is
 * never an unnamed control.
 *
 * Copy: the label names what happens, not the direction — "Add a participant",
 * not "Expand".
 */
export function ExpandButton({ icon, label, withChevron, expanded, className, type = 'button', ref, ...rest }: Props) {
  /* IT IS A <Button>, and it used to only look like one. Until 2026-08-31 this
   * drew its own pill: the brand fill, the hover step, the radius and the
   * pointer, all retyped in its own stylesheet. What it did not retype was the
   * focus ring, the disabled state and the pressed step, so the one control in
   * this family that was not built on Button was also the only one a keyboard
   * user could not see. Composing gets all four for free and leaves this
   * stylesheet with the one thing that is actually its own: the reveal. */
  return (
    <Button
      ref={ref}
      type={type}
      className={cn('expand-button', className)}
      aria-label={label}
      data-expanded={expanded || undefined}
      {...rest}
    >
      <Icon name={icon} size="md" />
      <span className="expand-button-label">{label}</span>
      {withChevron && <Icon name="arrow_drop_down" size="md" className="expand-button-chevron" />}
    </Button>
  )
}
